package glitch

import data.glitch_lib

# Unsafe protocols without integrity verification
unsafe_protocols := {"http", "ftp", "telnet", "udp", "tcp"}

# Security protocol indicators that provide integrity
integrity_protocols := {"https", "tls", "ssl", "dtls", "sftp", "scp", "ssh"}

# Checksum/integrity related attributes
checksum_keywords := {"checksum", "hash", "digest", "integrity", "verification", "validate", "hmac", "signature", "sign", "verify_checksum", "checksum_validation", "content_md5", "etag_validation", "consistency_check", "data_verification", "replication_checksum"}

# Disabled integrity indicators
disabled_integrity_keywords := {"disable_checksum", "checksum_disabled", "verify_checksum", "integrity_check", "hmac_verification", "signature_required", "verify", "validation"}

# Database SSL modes that don't verify integrity
unsafe_ssl_modes := {"disable", "disabled", "allow", "prefer", "false"}

# Database SSL modes that verify integrity
safe_ssl_modes := {"require", "verify-ca", "verify-full", "true", "enabled"}

# Sensitive resource types that should have integrity checks
sensitive_resource_types := {"database", "db", "connection", "replication", "listener", "endpoint", "loadbalancer", "gateway", "proxy", "message_queue", "mq", "queue", "topic", "cache", "storage", "bucket", "registry", "repository", "artifact"}

check_value_is_protocl_or_scheme(value) {
    value.ir_type == "String"
    lower(value.value) == unsafe_protocols[_]
}

check_has_integrity_protocol(value) {
    value.ir_type == "String"
    lower(value.value) == integrity_protocols[_]
}

check_has_integrity_protocol_in_complex(value) {
    value.ir_type == "Hash"
    some k, v
    v := value.value[k]
    check_has_integrity_protocol(v)
}

check_has_integrity_protocol_in_complex(value) {
    value.ir_type == "Array"
    some idx
    check_has_integrity_protocol(value.value[idx])
}

# Check if value explicitly disables integrity
check_disabled_integrity(attr_name, attr_value) {
    disabled_key_check(attr_name)
    attr_value.ir_type == "Boolean"
    attr_value.value == false
}

check_disabled_integrity(attr_name, attr_value) {
    disabled_key_check(attr_name)
    attr_value.ir_type == "String"
    lower(attr_value.value) == {"false", "disabled", "off", "no"}[_]
}

disabled_key_check(attr_name) {
    lower(attr_name) == disabled_integrity_keywords[_]
}

disabled_key_check(attr_name) {
    contains(lower(attr_name), "disable")
}

disabled_key_check(attr_name) {
    contains(lower(attr_name), "verify")
    contains(lower(attr_name), "false")
}

# Check SSL mode configuration for databases
check_unsafe_ssl_mode(attr_name, attr_value) {
    lower(attr_name) == "ssl_mode"
    attr_value.ir_type == "String"
    lower(attr_value.value) == unsafe_ssl_modes[_]
}

check_unsafe_ssl_mode(attr_name, attr_value) {
    lower(attr_name) == "ssl"
    attr_value.ir_type == "Boolean"
    attr_value.value == false
}

check_unsafe_ssl_mode(attr_name, attr_value) {
    lower(attr_name) == "encryption_in_transit"
    attr_value.ir_type == "Boolean"
    attr_value.value == false
}

# Check if attribute name suggests sensitive data transfer
is_sensitive_resource_type(type_str) {
    lower(type_str) == sensitive_resource_types[_]
}

contains_sensitive_type(type_str) {
    lower(type_str) == sensitive_resource_types[_]
}

contains_sensitive_type(type_str) {
