# Check for protocol/scheme attribute with unsafe value
has_unsafe_protocol_attribute(attrs) {
    attr := attrs[_]
    attr_name := lower(attr.name)
    (attr_name == "protocol" ; attr_name == "scheme" ; attr_name == "transport" ; attr_name == "communication_protocol" ; attr_name == "socket_type" ; attr_name == "backend_protocol" ; attr_name == "health_check_protocol" ; attr_name == "upstream_protocol" ; attr_name == "downstream_protocol")
    check_value_is_protocl_or_scheme(attr.value)
}

# Check if any integrity-related attribute exists
has_integrity_attribute(attrs) {
    attr := attrs[_]
    integrity_attr_check(attr.name)
}

