    contains(lower(attr_name), "verify")
}

integrity_attr_check(attr_name) {
    contains(lower(attr_name), "hmac")
}

integrity_attr_check(attr_name) {
    contains(lower(attr_name), "signature")
}

integrity_attr_check(attr_name) {
    contains(lower(attr_name), "sign")
}

# Check if attribute name indicates disabled integrity
has_disabled_integrity_attribute(attrs) {
    attr := attrs[_]
    check_disabled_integrity(attr.name, attr.value)
}

# Check for unsafe SSL mode
has_unsafe_ssl_mode(attrs) {
    attr := attrs[_]
    check_unsafe_ssl_mode(attr.name, attr.value)
}

# Main rule: Detect missing integrity check - unsafe protocol with no integrity verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check if resource type is sensitive
    contains_sensitive_type(node.type)

    attrs := glitch_lib.all_attributes(node)

    # Has unsafe protocol configured
    has_unsafe_protocol_attribute(attrs)

    # And no integrity attribute exists
    not has_integrity_attribute(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Sensitive resource uses unsafe protocol without integrity verification mechanism (CWE-353)"
    }
}

# Rule: Explicitly disabled integrity check
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)

    # Has explicitly disabled integrity
    has_disabled_integrity_attribute(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Integrity verification explicitly disabled (CWE-353)"
    }
}

# Rule: Database or storage with unsafe SSL/encryption mode
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check if resource type involves data transfer/storage
    (contains_sensitive_type(node.type) ; node.type == "AtomicUnit")

    attrs := glitch_lib.all_attributes(node)

    # Has unsafe SSL mode
    has_unsafe_ssl_mode(attrs)

    # And no alternative integrity mechanism
    not has_integrity_attribute(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Data transfer without integrity verification (CWE-353)"
    }
}

